//! Community-scoped authentication allowlist persistence.
//!
//! This store is distinct from NIP-43 relay membership. Membership backfill
//! orchestration remains with the relay-membership invariant owner.

use buzz_core::CommunityId;
use buzz_datastore_tracing::datastore_span;
use chrono::{DateTime, Utc};
use sqlx::Row;

use crate::error::Result;
use crate::Db;

/// An entry in the pubkey allowlist.
#[derive(Debug, Clone)]
pub struct AllowlistEntry {
    /// The allowed pubkey.
    pub pubkey: Vec<u8>,
    /// Who added this entry.
    pub added_by: Vec<u8>,
    /// When the entry was added.
    pub added_at: DateTime<Utc>,
    /// Optional note.
    pub note: Option<String>,
}

impl Db {
    /// Check if a pubkey is in the allowlist for `community`.
    #[datastore_span(name = "is_pubkey_allowed", system = "postgresql")]
    pub async fn is_pubkey_allowed(&self, community: CommunityId, pubkey: &[u8]) -> Result<bool> {
        let mut connection = crate::observability::acquire_writer(
            &self.pool,
            crate::observability::WriterOperation::Authentication,
        )
        .await?;
        let row = sqlx::query(
            "SELECT COUNT(*) as cnt FROM pubkey_allowlist WHERE community_id = $1 AND pubkey = $2",
        )
        .bind(community.as_uuid())
        .bind(pubkey)
        .fetch_one(&mut *connection)
        .await?;
        let cnt: i64 = row.try_get("cnt")?;
        Ok(cnt > 0)
    }

    /// Check if the community allowlist has any entries (i.e. is enforcement active).
    #[datastore_span(name = "has_allowlist_entries", system = "postgresql")]
    pub async fn has_allowlist_entries(&self, community: CommunityId) -> Result<bool> {
        let mut connection = crate::observability::acquire_writer(
            &self.pool,
            crate::observability::WriterOperation::Authentication,
        )
        .await?;
        let row =
            sqlx::query("SELECT COUNT(*) as cnt FROM pubkey_allowlist WHERE community_id = $1")
                .bind(community.as_uuid())
                .fetch_one(&mut *connection)
                .await?;
        let cnt: i64 = row.try_get("cnt")?;
        Ok(cnt > 0)
    }

    /// Add a pubkey to the community allowlist.
    #[datastore_span(name = "add_to_allowlist", system = "postgresql")]
    pub async fn add_to_allowlist(
        &self,
        community: CommunityId,
        pubkey: &[u8],
        added_by: &[u8],
        note: Option<&str>,
    ) -> Result<bool> {
        let mut connection = crate::observability::acquire_writer(
            &self.pool,
            crate::observability::WriterOperation::Authorization,
        )
        .await?;
        let result = sqlx::query(
            "INSERT INTO pubkey_allowlist (community_id, pubkey, added_by, note) VALUES ($1, $2, $3, $4) \
             ON CONFLICT DO NOTHING",
        )
        .bind(community.as_uuid())
        .bind(pubkey)
        .bind(added_by)
        .bind(note)
        .execute(&mut *connection)
        .await?;
        Ok(result.rows_affected() > 0)
    }

    /// Remove a pubkey from the community allowlist.
    #[datastore_span(name = "remove_from_allowlist", system = "postgresql")]
    pub async fn remove_from_allowlist(
        &self,
        community: CommunityId,
        pubkey: &[u8],
    ) -> Result<bool> {
        let mut connection = crate::observability::acquire_writer(
            &self.pool,
            crate::observability::WriterOperation::Authorization,
        )
        .await?;
        let result =
            sqlx::query("DELETE FROM pubkey_allowlist WHERE community_id = $1 AND pubkey = $2")
                .bind(community.as_uuid())
                .bind(pubkey)
                .execute(&mut *connection)
                .await?;
        Ok(result.rows_affected() > 0)
    }

    /// List all pubkeys in the community allowlist.
    #[datastore_span(name = "list_allowlist", system = "postgresql")]
    pub async fn list_allowlist(&self, community: CommunityId) -> Result<Vec<AllowlistEntry>> {
        let mut connection = crate::observability::acquire_writer(
            &self.pool,
            crate::observability::WriterOperation::Authorization,
        )
        .await?;
        let rows = sqlx::query(
            "SELECT pubkey, added_by, added_at, note FROM pubkey_allowlist WHERE community_id = $1 ORDER BY added_at DESC",
        )
        .bind(community.as_uuid())
        .fetch_all(&mut *connection)
        .await?;

        let mut out = Vec::with_capacity(rows.len());
        for row in rows {
            out.push(AllowlistEntry {
                pubkey: row.try_get("pubkey")?,
                added_by: row.try_get("added_by")?,
                added_at: row.try_get("added_at")?,
                note: row.try_get("note")?,
            });
        }
        Ok(out)
    }
}

#[cfg(test)]
mod postgres_tests {
    use super::*;
    use sqlx::PgPool;
    use uuid::Uuid;

    const TEST_DB_URL: &str = "postgres://buzz:buzz_dev@localhost:5432/buzz"; // sadscan:disable np.postgres.1 -- local test-only credentials

    async fn setup_db() -> Db {
        let database_url =
            std::env::var("TEST_DATABASE_URL").unwrap_or_else(|_| TEST_DB_URL.into());
        let pool = PgPool::connect(&database_url)
            .await
            .expect("connect to test DB");
        Db::from_pool(pool)
    }

    async fn make_community(pool: &PgPool) -> Uuid {
        let id = Uuid::new_v4();
        let host = format!("communities-of-channels-{}.example", id.simple());
        sqlx::query("INSERT INTO communities (id, host) VALUES ($1, $2)")
            .bind(id)
            .bind(host)
            .execute(pool)
            .await
            .expect("insert community");
        id
    }

    #[tokio::test]
    #[ignore = "requires Postgres"]
    async fn allowlist_is_scoped_to_community() {
        let db = setup_db().await;
        let community_a = CommunityId::from_uuid(make_community(&db.pool).await);
        let community_b = CommunityId::from_uuid(make_community(&db.pool).await);
        let pubkey = [7u8; 32];
        let added_by = [9u8; 32];

        assert!(db
            .add_to_allowlist(community_a, &pubkey, &added_by, Some("a-only"))
            .await
            .expect("add allowlist row"));
        assert!(!db
            .add_to_allowlist(community_a, &pubkey, &added_by, Some("duplicate"))
            .await
            .expect("duplicate allowlist row is idempotent"));

        assert!(
            db.is_pubkey_allowed(community_a, &pubkey)
                .await
                .expect("allowlist check A"),
            "pubkey added to A must be allowed in A"
        );
        assert!(
            !db.is_pubkey_allowed(community_b, &pubkey)
                .await
                .expect("allowlist check B"),
            "pubkey added only to A must not be allowed in B"
        );
        assert!(db
            .has_allowlist_entries(community_a)
            .await
            .expect("A has entries"));
        assert!(!db
            .has_allowlist_entries(community_b)
            .await
            .expect("B has no entries"));

        let listed = db
            .list_allowlist(community_a)
            .await
            .expect("list A allowlist");
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].pubkey, pubkey);

        assert!(
            !db.remove_from_allowlist(community_b, &pubkey)
                .await
                .expect("remove from B is no-op"),
            "removing from B must not delete A's row"
        );
        assert!(db
            .is_pubkey_allowed(community_a, &pubkey)
            .await
            .expect("A still allowed after B remove"));
        assert!(db
            .remove_from_allowlist(community_a, &pubkey)
            .await
            .expect("remove from A"));
        assert!(!db
            .is_pubkey_allowed(community_a, &pubkey)
            .await
            .expect("A not allowed after remove"));
    }
}

import type { PermissionContext, PermissionRule } from '@agentscope-ai/agentscope/permission';
import { Ban, CircleHelp, FolderOpen, ShieldCheck, ShieldX } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';

import { PanelEmpty } from '@/components/panel/PanelEmpty';
import { Badge } from '@/components/ui/badge';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { useTranslation } from '@/i18n/useI18n';

/** The behavior keys we render sections for (excludes ``passthrough``). */
type RuleBehavior = 'allow' | 'deny' | 'ask';

interface PermissionPanelProps {
	/**
	 * The permission context to render. Pass ``null`` when no data is
	 * available yet (renders an empty state).
	 */
	permissionContext: PermissionContext | null;
}

/** i18n key suffix for each behavior group title. */
const BEHAVIOR_META: Record<RuleBehavior, { i18nKey: string; icon: typeof ShieldCheck }> = {
	allow: { i18nKey: 'panel.permission.allow', icon: ShieldCheck },
	deny: { i18nKey: 'panel.permission.deny', icon: Ban },
	ask: { i18nKey: 'panel.permission.ask', icon: CircleHelp },
};

/**
 * A monospace value (a path or rule pattern) that truncates to fit its
 * row. When (and only when) the text is actually clipped, hovering
 * reveals the full value in a tooltip anchored to the left.
 *
 * @param value - The text to display.
 * @returns The truncating value element, with a tooltip when clipped.
 */
function TruncatedCode({ value }: { value: string }) {
	const ref = useRef<HTMLSpanElement>(null);
	const [truncated, setTruncated] = useState(false);

	useEffect(() => {
		const el = ref.current;
		if (!el) return;
		const check = () => setTruncated(el.scrollWidth > el.clientWidth);
		check();
		const observer = new ResizeObserver(check);
		observer.observe(el);
		return () => observer.disconnect();
	}, [value]);

	return (
		<Tooltip>
			<TooltipTrigger asChild>
				<span ref={ref} className="min-w-0 flex-1 truncate text-left font-mono text-xs">
					{value}
				</span>
			</TooltipTrigger>
			{truncated ? (
				<TooltipContent side="left" className="max-w-sm font-mono break-all">
					{value}
				</TooltipContent>
			) : null}
		</Tooltip>
	);
}

/**
 * A single tool's rule card: a header naming the tool plus one row per
 * matching rule (pattern on the left, source on the right).
 *
 * @param toolName - The tool these rules apply to.
 * @param rules - The rules configured for this tool under one behavior.
 * @returns The tool card element.
 */
function ToolRuleCard({ toolName, rules }: { toolName: string; rules: PermissionRule[] }) {
	const { t } = useTranslation();
	return (
		<div className="rounded-md border">
			<div className="flex items-center gap-x-2 border-b px-2 py-1.5 text-sm font-medium">
				{toolName}
				<Badge variant="secondary" className="ml-auto">
					{rules.length}
				</Badge>
			</div>
			<ul className="flex flex-col">
				{rules.map((rule, index) => (
					<li
						key={`${rule.rule_content ?? '*'}-${index}`}
						className="flex items-center justify-between gap-x-2 px-2 py-1.5 text-xs not-last:border-b"
					>
						{rule.rule_content ? (
							<TruncatedCode value={rule.rule_content} />
						) : (
							<span className="min-w-0 flex-1 text-muted-foreground">
								{t('panel.permission.anyInvocation')}
							</span>
						)}
						<Badge variant="outline" className="shrink-0">
							{rule.source}
						</Badge>
					</li>
				))}
			</ul>
		</div>
	);
}

/**
 * One behavior group (allow / deny / ask): a titled section that lists
 * a {@link ToolRuleCard} per tool that has rules under this behavior.
 *
 * @param behavior - The behavior category for this section.
 * @param ruleMap - Rules keyed by tool name for this behavior.
 * @returns The section element, or ``null`` when there are no rules.
 */
function BehaviorGroup({
	behavior,
	ruleMap,
}: {
	behavior: RuleBehavior;
	ruleMap: Record<string, PermissionRule[]> | undefined;
}) {
	const { t } = useTranslation();
	const entries = Object.entries(ruleMap ?? {}).filter(([, rules]) => rules.length > 0);
	if (entries.length === 0) return null;

	const meta = BEHAVIOR_META[behavior];
	const Icon = meta.icon;

	return (
		<div className="flex flex-col gap-y-1.5">
			<div className="flex items-center gap-x-1.5 text-xs font-medium text-muted-foreground">
				<Icon className="size-3.5" />
				{t(meta.i18nKey)}
			</div>
			{entries.map(([toolName, rules]) => (
				<ToolRuleCard key={toolName} toolName={toolName} rules={rules} />
			))}
		</div>
	);
}

/**
 * Pure content body for the Permission dock panel. Shows the active
 * permission mode, the working directories in scope, and the configured
 * rules grouped by behavior (deny / ask / allow) and then by tool. Data
 * arrives via props so it owns no data fetching.
 *
 * Renders without its own header/border — the surrounding `Panel`
 * chrome (from `PanelDock`) provides those.
 *
 * @param permissionContext - The permission context, or ``null``.
 * @returns The permission panel body.
 */
export function PermissionPanel({ permissionContext }: PermissionPanelProps) {
	const { t } = useTranslation();
	const workingDirs = Object.values(permissionContext?.working_directories ?? {});
	const hasRules =
		Object.keys(permissionContext?.allow_rules ?? {}).length > 0 ||
		Object.keys(permissionContext?.deny_rules ?? {}).length > 0 ||
		Object.keys(permissionContext?.ask_rules ?? {}).length > 0;

	return (
		<div className="flex flex-col flex-1 min-h-0 gap-y-3">
			<span className="text-muted-foreground text-sm">
				{t('panel.permission.description')}
			</span>

			<div className="flex flex-col flex-1 min-h-0 overflow-y-auto gap-y-4">
				{/* Working directories — always shown, with an empty state. */}
				<div className="flex flex-col gap-y-1.5">
					<div className="flex items-center gap-x-1.5 text-xs font-medium text-muted-foreground">
						<FolderOpen className="size-3.5" />
						{t('panel.permission.workingDirectories')}
					</div>
					{workingDirs.length === 0 ? (
						<p className="text-muted-foreground text-xs px-1 py-2">
							{t('panel.permission.noWorkingDirectories')}
						</p>
					) : (
						<ul className="flex flex-col rounded-md border">
							{workingDirs.map((dir) => (
								<li
									key={dir.path}
									className="flex items-center justify-between gap-x-2 px-2 py-1.5 text-xs not-last:border-b"
								>
									<TruncatedCode value={dir.path} />
									<Badge variant="outline" className="shrink-0">
										{dir.source}
									</Badge>
								</li>
							))}
						</ul>
					)}
				</div>

				{/* Rules grouped by behavior, then by tool. */}
				{hasRules ? (
					<>
						<BehaviorGroup behavior="deny" ruleMap={permissionContext?.deny_rules} />
						<BehaviorGroup behavior="ask" ruleMap={permissionContext?.ask_rules} />
						<BehaviorGroup behavior="allow" ruleMap={permissionContext?.allow_rules} />
					</>
				) : (
					<PanelEmpty
						icon={ShieldX}
						title={t('panel.permission.emptyTitle')}
						description={t('panel.permission.emptyDescription')}
					/>
				)}
			</div>
		</div>
	);
}

"""Host-neutral permission policy for automatic Turn execution."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from typing import Any, Protocol

from core.config import DeepCodeConfig, load_config_for_workspace
from core.domain.execution_permission import ExecutionPermissionMode


class AutomationPermissionPolicy(Protocol):
    """Resolve the permission snapshot for a workspace Automation Turn."""

    def resolve(self, workspace: str) -> ExecutionPermissionMode:
        """Return one explicit, durable execution mode."""


@dataclass(frozen=True, slots=True)
class WorkspaceAutomationPermissionPolicy:
    """Use explicit layered workspace configuration or a safe default.

    This resolver intentionally ignores the host surface and does not inspect
    Automation instructions. Resolution happens once at Turn admission and the
    typed result is persisted, so later workers consume the same decision.
    """

    config_loader: Callable[[str], DeepCodeConfig] = load_config_for_workspace
    default_mode: ExecutionPermissionMode = ExecutionPermissionMode.DEFAULT

    def resolve(self, workspace: str) -> ExecutionPermissionMode:
        security = getattr(self.config_loader(workspace), "security", None)
        raw = _explicit_permission_mode(security)
        if raw is None:
            return self.default_mode
        try:
            return ExecutionPermissionMode(raw.strip().lower())
        except ValueError:
            return self.default_mode


def _explicit_permission_mode(security: Any | None) -> str | None:
    if security is None:
        return None
    fields_set = getattr(security, "model_fields_set", None)
    if fields_set is None:
        fields_set = getattr(security, "__fields_set__", None)
    if fields_set is not None and "permission_mode" not in fields_set:
        return None
    value = getattr(security, "permission_mode", None)
    return str(value) if value is not None else None


__all__ = [
    "AutomationPermissionPolicy",
    "WorkspaceAutomationPermissionPolicy",
]

